import React from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";

function Events() {

  const navigate = useNavigate();

  const events = [
    {
      id: 1,
      name: "24 Hour Hackathon",
      date: "2026-04-10",
      venue: "Computer Lab",
      prize: "₹5000"
    },
    {
      id: 2,
      name: "Coding Contest",
      date: "2026-04-11",
      venue: "Seminar Hall",
      prize: "₹3000"
    },
    {
      id: 3,
      name: "Technical Quiz",
      date: "2026-04-12",
      venue: "Auditorium",
      prize: "₹2000"
    },
    {
      id: 4,
      name: "Cultural Dance",
      date: "2026-04-13",
      venue: "Main Stage",
      prize: "₹4000"
    }
  ];

  const handleRegister = (eventId) => {
    navigate(`/register/${eventId}`);
  };

  return (

    <div>

      <Navbar />

      <div style={{ padding: "30px" }}>

        <h2>College Events</h2>

        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(3, 1fr)",
          gap: "20px",
          marginTop: "20px"
        }}>

          {events.map((event) => (

            <div key={event.id} style={{
              border: "1px solid #ccc",
              padding: "20px",
              borderRadius: "10px",
              boxShadow: "0 0 10px rgba(0,0,0,0.1)"
            }}>

              <h3>{event.name}</h3>

              <p>Date: {event.date}</p>

              <p>Venue: {event.venue}</p>

              <p>Prize: {event.prize}</p>

              <button
                onClick={() => handleRegister(event.id)}
                style={{
                  padding: "8px 15px",
                  background: "#0984e3",
                  color: "white",
                  border: "none",
                  borderRadius: "5px",
                  cursor: "pointer"
                }}
              >
                Register
              </button>

            </div>

          ))}

        </div>

      </div>

    </div>

  );

}

export default Events;
